ee:variables.ee:set-variable:
%dw 2.0
output application/java
var prev = if (vars.collected is String) read(vars.collected, "application/json") else (vars.collected default {})
var t = vars.req.text default ""
var acct = (t match /.*?(\d{4})-?(\d{4}).*/)
var addr = (t match /.*?((東京都|北海道|京都府|大阪府|\S{2,3}県)[^\s、。,，]+).*/)
var ymd = (t match /.*?(\d{4})[-\/年](\d{1,2})[-\/月](\d{1,2}).*/)
var md = (t match /.*?(\d{1,2})月(\d{1,2})日.*/)
fun pad(s) = if (sizeOf(s as String) == 1) "0" ++ s else s
var date =
  if (!isEmpty(ymd)) ymd[1] ++ "-" ++ pad(ymd[2]) ++ "-" ++ pad(ymd[3])
  else if (!isEmpty(md)) "2026-" ++ pad(md[1]) ++ "-" ++ pad(md[2])
  else null
var merged = prev ++ {
  (accountNumber: acct[1] ++ "-" ++ acct[2]) if (!isEmpty(acct)),
  (newAddress: addr[1]) if (!isEmpty(addr)),
  (movingDate: date) if (date != null)
}
var fields = { accountNumber: merged.accountNumber, newAddress: merged.newAddress, movingDate: merged.movingDate }
---
{
  fields: fields,
  missing: [
    ("口座番号（例: 1002-0002）") if (fields.accountNumber == null),
    ("新しい住所（都道府県から）") if (fields.newAddress == null),
    ("転居日（例: 10月1日）") if (fields.movingDate == null)
  ],
  cancel: (t contains "キャンセル") or (t contains "取り消")
}

%dw 2.0
output application/json
var ts = now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSXXX"}
---
{
  kind: "task",
  id: vars.taskId,
  contextId: vars.contextId,
  status: {
    state: vars.state,
    timestamp: ts,
    message: {
      kind: "message",
      role: "agent",
      messageId: uuid(),
      taskId: vars.taskId,
      contextId: vars.contextId,
      parts: [ { kind: "text", text: vars.reply } ]
    }
  },
  artifacts: if (vars.state == "completed") [
    {
      artifactId: uuid(),
      name: "address-change-receipt",
      parts: [
        { kind: "data", data: { receiptNumber: vars.receipt } ++ vars.intake.fields }
      ]
    }
  ] else [],
  metadata: {}
}

ee:message.ee:set-payload:
%dw 2.0
output application/json
import try, orElse from dw::Runtime
fun show(v) = v match {
  case s is String -> (try(() -> read(s, "application/json")) orElse s)
  else -> (try(() -> write(v, "application/json") then read($, "application/json")) orElse (v as String default "?"))
}
---
(payload pluck ((v, k) -> { key: k as String, value: show(v) })) orderBy $.key
